-- Separate, rehearsal-only study database. No identity/name/account fields.
CREATE TABLE study_invites (code_hash TEXT PRIMARY KEY, participant_id TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE participants (participant_id TEXT PRIMARY KEY, trading_style TEXT NOT NULL, experience TEXT NOT NULL, device TEXT NOT NULL, session_date TEXT NOT NULL);
CREATE TABLE sessions (session_id TEXT PRIMARY KEY, participant_id TEXT NOT NULL REFERENCES participants(participant_id), token_hash TEXT NOT NULL UNIQUE, mode TEXT NOT NULL CHECK(mode='rehearsal'), consent_version TEXT NOT NULL, consented_at TEXT NOT NULL, app_version TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL CHECK(status IN ('active','finished','stopped')), UNIQUE(session_id,participant_id));
CREATE TABLE usage_events (event_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), sequence INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), received_at TEXT NOT NULL, UNIQUE(session_id,sequence));
CREATE TRIGGER immutable_study_event BEFORE INSERT ON usage_events WHEN EXISTS(SELECT 1 FROM usage_events WHERE event_id=NEW.event_id AND payload<>NEW.payload) BEGIN SELECT RAISE(ABORT,'event_conflict'); END;
CREATE TABLE tasks (session_id TEXT NOT NULL, participant_id TEXT NOT NULL, task_id TEXT NOT NULL, completed TEXT NOT NULL CHECK(completed IN ('yes','partly','no')), time_seconds REAL, needed_help TEXT CHECK(needed_help IN ('yes','no') OR needed_help IS NULL), evidence_opened TEXT NOT NULL CHECK(evidence_opened IN ('yes','no')), notes TEXT NOT NULL, measurement_source TEXT NOT NULL, PRIMARY KEY(session_id,task_id), FOREIGN KEY(session_id,participant_id) REFERENCES sessions(session_id,participant_id));
CREATE TABLE ratings (session_id TEXT NOT NULL, participant_id TEXT NOT NULL, item_id TEXT NOT NULL, score INTEGER CHECK(score BETWEEN 1 AND 5 OR score IS NULL), response_status TEXT NOT NULL, PRIMARY KEY(session_id,item_id), FOREIGN KEY(session_id,participant_id) REFERENCES sessions(session_id,participant_id));
CREATE TABLE comments (comment_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, participant_id TEXT NOT NULL, source TEXT NOT NULL, theme TEXT NOT NULL, quote TEXT NOT NULL, redaction_status TEXT NOT NULL, FOREIGN KEY(session_id,participant_id) REFERENCES sessions(session_id,participant_id));
